/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=person, operation=getAll
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get many activities */
export type PipedriveV2PersonGetAllParams = {
  resource: 'person';
  operation: 'getAll';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
/**
 * Whether to show raw Pipedrive field keys and option IDs instead of human-readable names in output
 * @default false
 */
    rawCustomFieldOutput?: boolean | Expression<boolean>;
/**
 * Filters
 * @default {}
 */
    filters?: {
    /** Filter persons whose name starts with this character (single character)
     */
    first_char?: string | Expression<string>;
    /** Predefined filter to apply to the persons to retrieve. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getFilters
     */
    filter_id?: string | Expression<string>;
  };
};

export type PipedriveV2PersonGetAllOutput = {
  add_time?: string;
  custom_fields?: Record<string, unknown>;
  emails?: Array<{
    label?: string;
    primary?: boolean;
    value?: string;
  }>;
  first_name?: string;
  id?: number;
  is_deleted?: boolean;
  label_ids?: Array<unknown>;
  last_name?: string;
  name?: string;
  org_id?: unknown;
  owner_id?: number;
  phones?: Array<{
    label?: string;
    primary?: boolean;
    value?: string;
  }>;
  picture_id?: unknown;
  update_time?: string;
  visible_to?: number;
};

export type PipedriveV2PersonGetAllNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2PersonGetAllParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2PersonGetAllOutput>;
};